import numpy as np
from collections import Counter, defaultdict

def read_xyz(fn):
    with open(fn) as f: lines=f.read().strip().split("\n")
    n=int(lines[0]); atoms=[]
    for l in lines[2:2+n]:
        p=l.split(); atoms.append((p[0],np.array([float(x) for x in p[1:4]])))
    return atoms

atoms = read_xyz("opt_free.xyz")
els=[a[0] for a in atoms]; xyz=[a[1] for a in atoms]
rcov={"H":0.31,"C":0.76,"N":0.71,"P":1.07,"Cl":1.02,"Ru":1.46}
bonds=set()
deg=defaultdict(int)
for i in range(len(atoms)):
    for j in range(i+1,len(atoms)):
        d=np.linalg.norm(xyz[i]-xyz[j])
        if d < 1.20*(rcov[els[i]]+rcov[els[j]]) :
            bonds.add((i,j)); deg[i]+=1; deg[j]+=1
print("perceived bonds:", len(bonds), "(expected 133)")
anom=[]
for i,e in enumerate(els):
    if e=="C" and deg[i] not in (3,4): anom.append((i,e,deg[i]))
    if e=="H" and deg[i]!=1: anom.append((i,e,deg[i]))
    if e=="N" and deg[i]!=3: anom.append((i,e,deg[i]))
    if e=="Cl" and deg[i]!=1: anom.append((i,e,deg[i]))
    if e=="P" and deg[i]!=4: anom.append((i,e,deg[i]))
print("anomalies:", anom if anom else "NONE")
print("degrees: Ru",deg[0],"Cbz",deg[3],"Cnhc",deg[16],"P",deg[65])
# bond type histogram
hist=Counter()
for i,j in bonds:
    hist[tuple(sorted((els[i],els[j])))] += 1
print(hist)
